fields.solution_code:
class Talaba:
    def __init__(self, ism, baholar):
        self.ism = ism
        self.baholar = baholar

    def ortacha(self):
        return sum(self.baholar) / len(self.baholar)

    def __str__(self):
        return f"{self.ism}: {self.ortacha():.2f}"

t = Talaba("Ozodbek", [5, 4, 5, 4])
print(t)
